/// Sounds played on a melee swing carrying a magic.
pub fn attack_magic(magic: u16) -> &'static [u16] {
    match magic {
        102 => &[156, 157], // Slaying: SlayingMale, SlayingFemale
        103 => &[158],      // Thrusting: EnergyBlast
        104 => &[159],      // HalfMoon: HalfMoon
        106 => &[160],      // FlamingSword: FlamingSword
        107 => &[161],      // DragonRise: DragonRise
        108 => &[162],      // BladeStorm: BladeStorm
        109 => &[164],      // DestructiveSurge: DestructiveSurge
        130 => &[163],      // DefensiveBlow: DefensiveBlow
        408 => &[284],      // CalamityOfFullMoon: CalamityOfFullMoon
        418 => &[283],      // WaningMoon: WaningMoon
        425 => &[162],      // FlameSplash: BladeStorm
        _ => &[],
    }
}

